catalog_ui_policy.script_true:
function onCondition() {

    var short_desc = g_form.getValue('short_description');
	var dev_future = g_form.getValue('device_future_state')
    if (short_desc == 'Ensue device is returned back to IT and Select Device future state') {
            g_form.setDisplay('device_future_state', true);
			g_form.setDisplay('device_cleaning_type', false);
			g_form.setMandatory('device_future_state', true);
			g_form.setReadOnly('device_future_state', false);
        }
		if (short_desc == 'Delete device from AD group'){
			g_form.setDisplay('device_future_state', false);
			g_form.setDisplay('device_cleaning_type', false);
		}
		if (short_desc == 'Wipe/Reset device' && dev_future == 'In stock'){
			g_form.setDisplay('device_future_state', true);
			g_form.setReadOnly('device_future_state', true);
			g_form.setDisplay('device_cleaning_type', true);
			g_form.setReadOnly('device_cleaning_type', false);
			g_form.setMandatory('device_cleaning_type', true);
		}
		if (short_desc == 'Wipe/Reset device' && dev_future == 'Retire') {
			g_form.setDisplay('device_future_state', true);
			g_form.setReadOnly('device_future_state', true);
			g_form.setDisplay('device_cleaning_type', false);
		}
		if (short_desc == 'Upload latest OS image in the device'){
			g_form.setDisplay('device_future_state', true);
			g_form.setDisplay('device_cleaning_type', true);
			g_form.setReadOnly('device_future_state', true);
			g_form.setReadOnly('device_cleaning_type', true);
		}
		if (short_desc == 'Reset device for future deliveries'){
			g_form.setDisplay('device_future_state', true);
			g_form.setDisplay('device_cleaning_type', true);
			g_form.setReadOnly('device_future_state', true);
			g_form.setReadOnly('device_cleaning_type', true);
		}
}
